import RNA
import random, sys, time

target='((..(((((........(.((..((.(.....(....).((((((((.........((......((((.....))))......))...((..((.......(..(......)..)..((..((.....((....)).((((.....(((.....(..((.(...).))..).....))).((((...(.......(..(.((...)).)..).......)...))))........)))).....((((((...)))))).))..))...........))..)).........(..((((....))((((((.....(........).....))))))..))..)...))))))))........).))..)).).....(.......).)))))..)).'
n=len(target)
assert len(target)==398

stack=[]; pair=[-1]*n
for i,c in enumerate(target):
    if c=='(': stack.append(i)
    elif c==')':
        j=stack.pop(); pair[i]=j; pair[j]=i

def fold(seq):
    return RNA.fold(seq)

def spairs(s):
    st=[]; sp=[-1]*n
    for i,c in enumerate(s):
        if c=='(': st.append(i)
        elif c==')':
            j=st.pop(); sp[i]=j; sp[j]=i
    return sp

def bpdist(s):
    sp=spairs(s)
    miss=sum(1 for i in range(n) if pair[i]!=-1 and sp[i]!=pair[i])
    spur=sum(1 for i in range(n) if sp[i]!=-1 and pair[i]!=sp[i])
    return (miss+spur)//2

# Smarter init: use GC for ALL base pairs but add destabilizing unpaired regions
# Actually use mixed: GC for outer/long stems, AU for weak isolated stems
# Identify stems (consecutive pairs)
stem_id=[-1]*n
sid=0
stems=[]
i=0
while i<n:
    if target[i]=='(' and pair[i]>i:
        # start of a stem
        a=i; b=pair[i]
        j=i
        length=0
        while j<n and pair[j]==pair[i]-0 if False else (pair[j]==b-length if pair[j]!=-1 else False):
            length+=1
            j+=1; 
        # simpler: count consecutive
        length=0
        j=i
        while pair[j]==b-length and pair[j]!=-1:
            length+=1; j+=1
        for k in range(length):
            stem_id[i+k]=sid; stem_id[b-k]=sid
        stems.append((i,b,length))
        sid+=1
        i=j
    else:
        i+=1

def init_seq(gc_frac=0.6):
    seq=['A']*n
    import random as r
    for (a,b,L) in stems:
        # GC for outermost (long-range) and length>=3; mix for isolated
        for k in range(L):
            if L>=3 or r.random()<gc_frac:
                seq[a+k]='G'; seq[b-k]='C'
            else:
                seq[a+k]='A'; seq[b-k]='U'
    for i in range(n):
        if pair[i]==-1:
            seq[i]=r.choice('ACU')  # avoid G in loops (less stable spurious)
    return ''.join(seq)

best_seq=None; best_d=999
random.seed(0)
t0=time.time()
trial=0
while time.time()-t0 < 120:
    trial+=1
    cand=init_seq(0.5)
    s,mfe=fold(cand)
    d=bpdist(s)
    if d<best_d:
        best_d=d; best_seq=cand
        print('trial',trial,'dist',d,file=sys.stderr)
print('best init dist',best_d,'trials',trial,file=sys.stderr)
sys.stdout.write(best_seq+'\n')
PYEOF
